import { useEffect, useRef, useState, type CSSProperties } from "react"
import data from "@/content/ambient.json"
import { cn } from "@/lib/utils"

/** Tiny blur sources and tones, generated by scripts/ambient.py. */
const ambient = data as Record<string, { img: string; tone: string }>

/**
 * Ambient light: a huge, heavily blurred copy of whatever is in focus, bleeding into
 * the black behind the content. Crossfades when `source` changes; the old layer is
 * dropped once the new one has fully faded in.
 * `source` is a key in ambient.json: a photo name, or "track:<slug>".
 */
export function Ambient({ source, strength, className }: { source: string | null; strength: number; className?: string }) {
  const [layers, setLayers] = useState<{ key: string; id: number }[]>([])
  const id = useRef(0)

  useEffect(() => {
    if (!source || !ambient[source]) return
    setLayers((l) => (l.at(-1)?.key === source ? l : [...l.slice(-1), { key: source, id: ++id.current }]))
    const t = setTimeout(() => setLayers((l) => l.slice(-1)), 1400)
    return () => clearTimeout(t)
  }, [source])

  return (
    <div aria-hidden className={cn("ambient pointer-events-none overflow-hidden", className)} style={{ opacity: strength }}>
      {layers.map(({ key, id }) => {
        const a = ambient[key]
        return <div key={id} className="ambient-img animate-in fade-in duration-[1200ms]" style={{ backgroundColor: a.tone, backgroundImage: `url(${a.img})` } as CSSProperties} />
      })}
    </div>
  )
}
